pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.prank(caller);
        try c.setOwner(newOwner) {} catch {}
        if (caller == c.owner()) {
            assertEq(c.owner(), newOwner, "owner should be newOwner if caller was owner");
        } else {
            assertTrue(true, "irrelevant when caller not owner");
        }
    }
}

