// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, address newOwner) public {
        // Ensure sender is not address(0) to avoid prank issues
        vm.assume(sender != address(0));
        // Ensure the current owner is the sender so the call does not revert due to onlyOwner
        vm.prank(c.owner());
        c.setOwner(sender);
        // Now sender is the owner, prank as sender and attempt to set new owner
        vm.prank(sender);
        bool success = c.setOwner(newOwner);
        // The call should succeed (onlyOwner passes) and state must reflect the argument
        assertTrue(success && c.owner() == newOwner);
    }
}

